239	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
240	        this.possibleDuplicateOf = possibleDuplicateOf;
241	    }
242	
243	    /**
244	     * The owner's salutation, derived at read time as the {@link #getTitle() title}, a single space
245	     * and the {@link #getLastName() lastName} (e.g. {@code 'DR Franklin'}); just the lastName when no
246	     * title is present.
247	     */
248	    @Transient
249	    public String getSalutation() {
250	        if (this.title == null || this.title.isBlank()) {
251	            return this.getLastName();
252	        }
253	        return this.title + " " + this.getLastName();
254	    }
255	
256	    /**
257	     * The owner's membership points, derived at read time from stored fields. Starts at 0; add 2 when
258	     * an email is present; add 1 when {@link #getNamesakeCount() namesakeCount} is 0; add 2 for a
259	     * household of 3 or more ({@link #getHouseholdSize() householdSize}); add 3 when tenure (days since
260	     * {@link #getRegistrationDate() registrationDate}) exceeds 365. A newly created owner has zero
261	     * tenure, so a new owner can score at most 5 points.
262	     */
263	    @Transient
264	    public Integer getMembershipPoints() {
265	        int points = 0;
266	        boolean hasEmail = this.email != null && !this.email.isBlank();
267	        if (hasEmail) {
268	            points += 2;
269	        }
270	        if (this.namesakeCount != null && this.namesakeCount == 0) {
271	            points += 1;
272	        }
273	        if (this.householdSize != null && this.householdSize >= 3) {
274	            points += 2;
275	        }
276	        if (this.registrationDate != null
277	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
278	            points += 3;
279	        }
280	        return points;
281	    }
282	
283	    /**
284	     * The owner's membership level, a number from 1 to 4 derived at read time by banding
285	     * {@link #getMembershipPoints() membershipPoints}: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
286	     * Because a new owner scores at most 5 points, only tenure (+3) can reach level 4.
287	     */
288	    @Transient
289	    public Integer getMembershipLevel() {
290	        int points = getMembershipPoints();
291	        if (points <= 1) {
292	            return 1;
293	        }
294	        if (points <= 3) {
295	            return 2;
296	        }
297	        if (points <= 5) {
298	            return 3;
299	        }
300	        return 4;
301	    }
302	
303	    /**
304	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
305	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
306	     * ignored). {@code null} when the owner has no customerCode.
307	     */
308	    @Transient
309	    public Integer getCheckDigit() {
310	        if (this.customerCode == null) {
311	            return null;
312	        }
313	        int sum = 0;
314	        boolean dbl = true;
315	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
316	            char c = this.customerCode.charAt(i);
317	            if (c < '0' || c > '9') {
318	                continue;
319	            }
320	            int d = c - '0';
321	            if (dbl) {
322	                d *= 2;
323	                if (d > 9) {
324	                    d -= 9;
325	                }
326	            }
327	            sum += d;
328	            dbl = !dbl;
329	        }
330	        return (10 - (sum % 10)) % 10;
331	    }
332	
333	    /**
334	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
335	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
336	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
337	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
338	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
339	     * yields {@code 'UNKNOWN'}.
340	     */
341	    @Transient
342	    public String getLocality() {
343	        String byPostcode = regionForPostcode(this.postcode);
344	        if (byPostcode != null) {
345	            return byPostcode;
346	        }
347	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
348	    }
349	
350	    /**
351	     * The owner's IANA timezone, derived at read time from the owner's region
352	     * ({@link #getLocality()}) via the pinned region-to-timezone table (NSW->Australia/Sydney,
353	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane). {@code null} when the region is unknown.
354	     */
355	    @Transient
356	    public String getTimezone() {
357	        return REGION_TIMEZONE.get(getLocality());
358	    }
359	
360	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
361	    private static String regionForPostcode(String postcode) {
362	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
363	            return null;
364	        }
365	        int value = Integer.parseInt(postcode);
366	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
367	            int[] range = entry.getValue();
368	            if (value >= range[0] && value <= range[1]) {
369	                return entry.getKey();
370	            }
371	        }
372	        return null;
373	    }
374	
375	    /**
376	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans, derived at read
377	     * time: the country code, a space, then the national digits grouped in threes (e.g.
378	     * {@code '+61412345678'} yields {@code '+61 412 345 678'}). Known country codes ({@code '+61'},
379	     * {@code '+1'}) are split off explicitly; otherwise a two-digit country code is assumed. The
380	     * raw {@link #getTelephone() telephone} itself stays in E.164 form. {@code null} when the owner
381	     * has no telephone or it is not a well-formed E.164 number.
382	     */
383	    @Transient
384	    public String getTelephoneDisplay() {
385	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
386	            return null;
387	        }
388	        String digits = this.telephone.substring(1); // drop the leading '+'
389	        String countryCode = countryCodeOf(digits);
390	        String national = digits.substring(countryCode.length());
391	        StringBuilder display = new StringBuilder("+").append(countryCode);
392	        display.append(' ');
393	        for (int i = 0; i < national.length(); i++) {
394	            if (i > 0 && i % 3 == 0) {
395	                display.append(' ');
396	            }
397	            display.append(national.charAt(i));
398	        }
399	        return display.toString();
400	    }
401	
402	    /**
403	     * The E.164 country code at the start of {@code digits} (the '+'-stripped number). Known codes
404	     * are matched longest-first; any other number falls back to a two-digit country code.
405	     */
406	    private static String countryCodeOf(String digits) {
407	        for (String code : KNOWN_COUNTRY_CODES) {
408	            if (digits.startsWith(code) && digits.length() > code.length()) {
409	                return code;
410	            }
411	        }
412	        return digits.length() > 2 ? digits.substring(0, 2) : digits;
413	    }
414	
415	    /** Recognised E.164 country codes, longest-first, for {@link #getTelephoneDisplay()}. */
416	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
417	
418	    /**
419	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
420	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
421	     */
422	    @Transient
423	    public String getContactPreference() {
424	        boolean hasEmail = this.email != null && !this.email.isBlank();
425	        return hasEmail ? "EMAIL" : "PHONE";
426	    }
427	
428	    /**
429	     * The owner's age band, derived at read time from {@link #getBirthDate() birthDate} measured
430	     * against the {@link #getRegistrationDate() registrationDate}: {@code 'MINOR'} when the owner is
431	     * under 18 at registration, {@code 'ADULT'} from 18 to 64, {@code 'SENIOR'} at 65 or over.
432	     * {@code null} when the owner has no birthDate (or no registrationDate to measure against).
433	     */
434	    @Transient
435	    public String getAgeBand() {
436	        if (this.birthDate == null || this.registrationDate == null) {
437	            return null;
438	        }
439	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
440	        if (years < 18) {
441	            return "MINOR";
442	        }
443	        if (years < 65) {
444	            return "ADULT";
445	        }
446	        return "SENIOR";
447	    }
448	
449	    /**
450	     * The single derived duplicate-detection key, {@code normalizedTelephone|email|householdId}
451	     * (the normalized telephone, the email or empty when absent, and the householdId or empty when
452	     * the owner has a unique household). All duplicate detection is expressed through this one key:
453	     * a create whose WHOLE identityKey equals an existing owner's is a duplicate. Because the
454	     * telephone is part of the key, two members of the same household with different telephones have
455	     * different identityKeys and are both allowed.
456	     */
457	    @Transient
458	    public String getIdentityKey() {
459	        String tel = this.telephone == null ? "" : this.telephone;
460	        String mail = (this.email == null || this.email.isBlank()) ? "" : this.email;
461	        String household = (this.householdId == null || this.householdId.isBlank()) ? "" : this.householdId;
462	        return tel + "|" + mail + "|" + household;
463	    }
464	
465	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
466	    private static final Map<String, String> CITY_REGION =
467	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
468	
469	    /** Region -> IANA timezone for {@link #getTimezone()}. */
470	    private static final Map<String, String> REGION_TIMEZONE =
471	        Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
472	
473	    /** Region -> inclusive 4-digit postcode range {low, high}, preferred by {@link #getLocality()}. */
474	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
475	        "NSW", new int[] {2000, 2099},
476	        "VIC", new int[] {3000, 3099},
477	        "QLD", new int[] {4000, 4099});
478	
479	    protected Set<Pet> getPetsInternal() {
480	        if (this.pets == null) {
481	            this.pets = new HashSet<>();
482	        }
483	        return this.pets;
484	    }
485	
486	    protected void setPetsInternal(Set<Pet> pets) {
487	        this.pets = pets;
488	    }
489	
490	    public List<Pet> getPets() {
491	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
492	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
493	        return Collections.unmodifiableList(sortedPets);
494	    }
495	
496	    public void setPets(List<Pet> pets) {
497	        this.pets = new HashSet<>(pets);
498	    }
499	
500	    public void addPet(Pet pet) {
501	        getPetsInternal().add(pet);
502	        pet.setOwner(this);
503	    }
504	
505	    /**
506	     * Return the Pet with the given name, or null if none found for this Owner.
507	     *
508	     * @param name to test
509	     * @return true if pet name is already in use
510	     */
511	    public Pet getPet(String name) {
512	        return getPet(name, false);
513	    }
514	
515	    /**
516	     * Return the Pet with the given name, or null if none found for this Owner.
517	     *
518	     * @param name to test
519	     * @return true if pet name is already in use
520	     */
521	    public Pet getPet(String name, boolean ignoreNew) {
522	        name = name.toLowerCase();
523	        for (Pet pet : getPetsInternal()) {
524	            if (!ignoreNew || !pet.isNew()) {
525	                String compName = pet.getName();
526	                compName = compName.toLowerCase();
527	                if (compName.equals(name)) {
528	                    return pet;
529	                }
530	            }
531	        }
532	        return null;
533	    }
534	
535	    public Pet getPet(Integer petId) {
536	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
537	    }
538	
539	    @Override
540	    public String toString() {
541	        return new ToStringCreator(this)
542	
543	            .append("id", this.getId())
544	            .append("new", this.isNew())
545	            .append("lastName", this.getLastName())
546	            .append("firstName", this.getFirstName())
547	            .append("address", this.address)
548	            .append("city", this.city)
549	            .append("telephone", this.telephone)
550	            .toString();
551	    }
552	}
